add('I','02209','历史成效与当前支持的边界','支持1：本句具体陈述已实施60日机制、约50日平均用时及创新研发支持作用，超出口号。支持0：这是历史成效背景，未当前开放、适用或限制某支持权利；手册排除历史状态展开全部待遇。应核定实质历史政策功能论述是否独立属I，不能从60/50数字自动展开。','member finite I3','边界待定')
add('I','02213','当前增设确定加快通道','当前统筹资源在60日基础上增设30日通道，明确再提速；为此承接创新研发加速需求，属于具体创新研发办理便利。区别于历史背景，时间比较不是猜测。','finite member I3')
add('I','02222','创新对象依申请获得加快机会','当前重点创新药依申请纳入30日通道，完整同版明确该通道相对60日提速和资源倾斜。对象、机会、关系具体，不把国家支持身份视作创新评价本身。','finite member I3')
add('I','02224','同步创新研发与实际通道纳入','同段明确创新药早期/同步研发，当前支持其中合条件品种和国际多中心试验纳入已核明30日通道。I3因研发便利成立，不认为全部全球同步对象都有技术新颖性。','finite member I3')
add('I','02229','当前资源明确向创新研发倾斜','当前直接规定审评资源向符合条件的创新临床申请倾斜，30日通道为确定的可用机制；即使忽略额外doc引文，当前原文足以建立I3三项，非一般鼓励。','I3')
add('I','02235','自足创新研发办理便利','本句直接规定合条件创新药临床申请受理后30工作日完成审评；对象、具体便利、直接联系自足。规则以一般身份/鼓励排除清空实际安排。','I3')
add('I','02236','具名通道实际支持研发对象','当前30日通道支持重点创新研发，前条直接规定30工作日完成审评。按具名支持的有限确指成立I3，临床急需及产业发展等并列导向不单独计I。','finite member I3')
add('I','02238 02239 02240 02241','成员与直接父谓词组成支持准入','当前成员或其自身解释与直接父条款组成1类创新临床申请可纳入30日通道的条件命题，通道明确提供30工作日便利。不是从儿童/罕见病/同步或期别词推创新，也未继承兄弟项所有内容；I4资格使用与I3申请支持关系有实际后果。','member finite I3 I4')
add('F','00128','当前实际按需优先办理','当前明确优先核查、检验和名称核准；完整同版资格的急需短缺分支因缺口获得这项同阶段优先资源。F限于该分支，不能将所有创新项目称为缺药或把普通检验都赋F。','finite member Fgap Fbranches Fservice')
add('F','00130','期限承接优先检验与纯手续边界','支持1是前项明确同阶段优先核查检验及缺口资格，本句可作为实质服务执行。支持0是当前只有完成与反馈时限，手册明确排除一般截止日期。须核定直接承接门槛，不能凭25日或整个优先程序自动计F。','member Fadmin Ftime Fservice','边界待定')
add('F','00131','特定药品检验流程与按需资源边界','当前目标单品种急需、境内未上市，与同版优先检验及70日通道有联系；但本句主要为2日通知、检验截止和报告反馈，纯通知/日期明确排除。15日前较25日前并不自证更快，须核定其是否实质承载按需优先资源。既有A/B=0保持固定，本AI争点不变成人工复核或替换参照。','member Fadmin Ftime Fservice','边界待定')
add('F','00144','资格内容的实质信息要求','当前要求详细说明优先情形、条件和证明，完整同版含急需短缺、市场短缺儿童药及无有效儿童治疗分支。当前要求的是相应按需优先资格内容，不从申请书格式或文件流转推出F。','finite member Fgap Fbranches Fadmin')
add('F','00246','试验数据缺失与治疗获取限制','支持1：同段高龄者被试验排除，数据缺失明确将限制临床治疗，可读为治疗机会差异。支持0：本句主要陈述证据不足和安全风险，并未明示无法取得所需药品或保障机会；一般试验参与不能替代F。需要核定数据证据缺口何时成为治疗获取障碍，暂不把安全不足自动改作公平。','member Fgap Ftrial','边界待定')
add('F','00247','及早补研究与按需保障边界','因此承接老年数据缺失限制治疗并要求及早研究，支持按群体需要补足资源；反方是当前重在用药安全与普通研究建议，未明确药品获取或针对性机会分配。一般老年身份与安全研究不充分，暂保留上述数据缺口的F门槛。','member Fgap Ftrial','边界待定')
add('F','00274','明确无药可治与全受试者治疗机会','当前无标准治疗/无药可治且急迫需要，并以早期突出疗效为条件免安慰剂/BSC、让入组者均有潜在治疗机会。明确缺口—针对性机会分配超过一般试验分组，未证明最终效果或所有随机试验不公平。','Fgap Ftrial')
add('F','00553','治疗紧急程度与药品优先保障','当前急危重需要、抢救药品可用、紧急调配及优先救治直接相连，是不同治疗需要与适当保障配置。无需推断现实断供或收入差异；一般设备可用/病人分类单独不足。','Fgap')
add('F','00612','明确公平信息内容公示','当前以申报药品为对象，明确公平性方面的信息公示征求意见，符合概括公平信息路径；无需另造具体障碍。与只公开名单、确认字段非空、程序透明度不同。','Finfo member')
add('F','00654','普通领域申报不能继承后句保障缺口','当前不限定领域是普通申报开放，未自身要求公平评价或明确保障缺口。后句才以保障不足/空白取消上市时限，不得反向给本句；更支持native0，规则用所有用药需要的天然背景推F过宽。','member Fgap Fadmin')
add('F','00655','保障空白与定向申请豁免','当前明确基本目录保障不足或空白的领域，并因此对儿童/罕见病等取消上市时间限制，填补用药需求短板。缺口—针对申请机会关系自足，不推定所有儿童/罕见病无药或已经支付。','Fgap member')
add('F','00663 00918','基本保障缺口与补充目录机会','当前主要面向因保基本定位暂不能纳入基本目录但患者获益显著的治疗药品，具体设置商保目录及多层次保障参考机会。仅记录基本保障范围缺口与补充机会，不推定患者收入不足、已实际承保或已改善公平；普通商保目录名称不足。','Fgap member finite')
add('F','01358','儿童所需药品与遴选限制豁免','当前以明确儿童适应证/用法用量所需品种为对象，豁免一品两规和品种总数限制，增加儿童用药范围。可指认制度限制与按需要的机会扩展直接相连，不由儿童身份推断缺货，也不把精准给药便利单独计F。','Fgap member')
add('F','01442 01443 01444','同一计划缺口资格与具体早期服务','当前实际开展计划、早期介入一品一策或开发计划讨论；完整同版资格②明示境内无获批目标适应症药物，作为申请/纳入条件进入这些具体研发支持资源。F只限该真实缺口分支，背景多数罕见病无药不能替代资格核验，FIC/优势兄弟支不继承F。','finite member Fgap Fbranches Fservice')
add('F','01445','缺口资格与纳入后持续服务','当前纳入后档案用于全程高效沟通，完整同版纳入后里程碑/回复机制明示可用服务，资格②缺口条件可进入该资源。须保留同阶段链，不借申报前机会代替；不是说全部纳入药品缺药。','finite member Fgap Fbranches Fservice')
add('F','01447 01463','自身创新性定义包含缺口申请支','当前较强创新性条件的自身完整定义②为境内无获批目标适应症药物，直接作为计划申请条件，而非并列FIC支的外来含义。该缺口支连接核明研发支持机会，可计F；名字叫创新性不改变其实质内容，也不使③临床优势变成无有效药。','member Fgap Fbranches')
add('F','01453','缺口条件进入明确支持申请机会','当前开放自愿申请加入已核明的研发支持计划，资格②以境内无获批目标治疗选项决定可申请范围。实质开放机会可以有限补对象和资源，普通渠道或备注填写句不可套用。','finite member Fgap Fbranches Fadmin')
add('F','01454 01467','名额限制直接涉及按需支持开放范围','当前不设名额限制实际规定同一支持计划的机会范围，缺口资格②可进入开发讨论和持续服务。依据为实质资源机会开放而非企业名额本身等于患者公平；五年数字无独立F意义。','finite member Fgap Fbranches Ftime')
add('F','01455','准予资源进入的评审服务','当前实际团队评价是否同意纳入及必要会议，决定能否进入完整同版研发支持；资格②缺口条件参与此决定关系。不是所有评审会议或材料收件都按需公平，F限该缺口—准入资源链。','finite member Fgap Fbranches Fadmin')
add('F','01468','完整资格决定拟纳入资源','当前明确援引1.1完整资格并据此拟纳入，②境内无获批目标治疗选项与核明开发讨论/持续服务的准入直接相连；不是仅提到资格名称或普通收件，不扩大到所有或分支。','finite member Fgap Fbranches')
add('F','01482','实际服务承接本计划缺口选择条件','当前直接向已纳入品种实施跟踪随访和研发沟通。完整同版CARE-P025②将无境内获批目标选项作为申请分支，P030以完整资格决定纳入，P007及P111/P112核明其具体同阶段服务；缺口条件进入特殊研发资源的链闭合，较支持规则1。不是仅用罕见病身份或所有研发需要：若无缺口资格、只属FIC/优势分支或只报告/通知，不成立F。native0指出无优先词，但冻结手册按需支持资源机会不要求该词；应保留此争点供人工核定，不能称用户已新确认1。','finite member Fgap Fbranches Fservice','更支持规则')
add('F','01541','缺口资格与纳入后里程碑支持','当前双方共同商定纳入后关键节点沟通，是具体服务；同版资格②缺口经纳入标准进入这一资源，F仅该分支。节点日期本身、罕见病身份或申报前沟通均不是依据。','finite member Fgap Fbranches Fservice')
